+      if (tab) return tab;
```

🟡 **Medium** `layout/layoutModel.ts:1495`

A background insertion into another workspace switches the user away from their focused empty workspace and removes it. `normalizeLayout(next)` runs before `keepLayoutFocus`, so it deletes the now-unfocused workspace before focus can be restored; restore focus before normalizing when `options.focus` is false.

```diff
-  next = normalizeLayout(next);
+  next = options.focus ? normalizeLayout(next) : normalizeLayout(keepLayoutFocus(state, next));
   if (options.focus) {
     const shown = options.activate ?? first.id;
     return focusLayoutTab(next, findLayoutTab(next, (tab) => tab.id === shown) ? shown : first.id);
   }
-  return keepLayoutFocus(state, next);
+  return next;
```

